INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(13900, 0, 139, 0, 0, 0, 'Eastern Plaguelands', 'Before the plague these hills and forests were the Eastweald, the eastern heart of Lordaeron, governed from Stratholme, the second city of the kingdom. Here Prince Arthas put Stratholme to the sword rather than let its plagued people rise, and here the Scourge made its deepest home. Blight has swallowed the land. Rot runs through the woods, plaguehounds and plaguebats hunt the hills, and towns such as Darrowshire, Corin''s Crossing and Northdale belong to the dead. Baron Rivendare rules Stratholme for Kel''Thuzad, and until lately the necropolis Naxxramas hung above the Plaguewood, before it floated away to Northrend. The living hold on where they can. The Argent Dawn keeps Light''s Hope Chapel, the Scarlet Crusade rules Tyr''s Hand, Mossflayer trolls cling to Zul''Mashar and high elf rangers guard a lodge near the road to Quel''Thalas. An exiled paladin lives as a hermit by the Thondroril, the Forsaken champion Nathanos Blightcaller hunts from his old farm, and the death knights'' fortress of Acherus now floats above the eastern hills.', 'warcraft.wiki.gg/wiki/Eastern_Plaguelands (Eastweald, regional government in Stratholme, Culling, Naxxramas over the Plaguewood then moved to Dragonblight, Acherus over the eastern part of the zone in Wrath); quest 5263 description (Kel''Thuzad''s errand boy rules over Stratholme: Baron Rivendare); quest 5543 description (wildlife transformed into man eating beasts); quest 5961 description (Nathanos at the Marris Stead); zone_areas: Mossflayer trolls in 2273, high elf rangers in 2276, Scarlet Crusade in 2266, Argent Dawn in 2268'),
(13901, 1, 139, 1, 0, 0, 'The Thondroril River', 'The Thondroril runs south along the western edge of the Eastern Plaguelands, the border with the western lands. On its bank stands a small hut where an old hermit lives with his horse, Mirador. He asks little of visitors beyond help keeping the plaguehounds and plaguebats at bay, and he is laying in carrion worm meat for the winter, since the grubs are the only beasts in the region the plague has left untouched. He asks every guest to honor one credo: race does not dictate honor. His name, when he finally gives it, is Tirion Fordring. Crypt fiends of the Scourge prowl the hills not far from his door.', 'AreaTable: 2619 Thondroril River, parent 139; posarea: Tirion Fordring 1855 and Mirador 11710 stand in area 2619; warcraft.wiki.gg/wiki/Tirion_Fordring (cottage on the shores of the Thondroril River, horse Mirador); quests 5542, 5543, 5544 descriptions (plaguehounds, plaguebats, carrion worms the only beasts unaffected, food for winter); npc_text 4254 (race does not dictate honor); zone_areas 2619: Crypt Horror, Crypt Stalker, Crypt Walker, Crypt Slayer; western_plaguelands.json 2810 (Thondroril runs along the border)'),
(13902, 1, 139, 2, 0, 0, 'The Marris Stead', 'The Marris Stead in the southwest was the family farm of Nathanos Marris, a ranger lord of Lordaeron. When the Scourge swept over the stead he stood his ground and was cut down, and rose again as one of the dead. Freed since by the Banshee Queen, he has come home as Nathanos Blightcaller, her champion. He keeps his blighthounds here and receives the recruits she sends to train under him, few of whom he thinks worth the trouble. Skulls and mangled human remains lie about the fields, among them what is left of the Alliance spies who came looking for the Blightcaller.', 'warcraft.wiki.gg/wiki/Marris_Stead (home of Nathanos Marris, killed there by Ramstein, returned on Sylvanas'' orders with his blighthounds); quest 6163 description (On this very stead I stood... I woke as Scourge); quest 5961 description (resides at the Marris Stead); npc_text 4814 (sent every one of you back to her in pieces); zone_areas 2260: Nathanos 11878, Blighthound 11885 x2, Human Skull 12202 x8, Mangled Human Remains 177804-177806; quest 6185 (SI:7 insignias, the lost agents); gameobject_loot: 177804-177806 Mangled Human Remains hold SI:7 Insignia (Fredo, Turyen, Rutger)'),
(13903, 1, 139, 3, 0, 0, 'The Undercroft', 'The Undercroft is an old crypt in the far southwest of the Eastern Plaguelands. One of its graves is a lie: when Tirion Fordring was exiled for treason, his wife told their son that he had died, and the boy was brought here to mourn at a false grave, where he buried his favorite toy hammer along with his father''s memory. The crypt now shelters dead troll thieves under Zaeldarr the Outcast, who raid the corpse pit at Light''s Hope Chapel by night and carry bodies back here. A torn scroll by the crypt tells of a doomed troll named Hameya and a chest buried in the dirt behind it.', 'quest 5781 description (false grave at the Undercroft, hammer buried with my memory); quest 6021 description (dead troll thieves, Zaeldarr, steal bodies from the pit, hideout the Undercroft to the west); quest 6024 description (scroll: chest buried behind this crypt); zone_areas 2261: Zaeldarr 12250, Unliving Mossflayer, Mossflayer Zombie, Torn Scroll 177667, Mound of Dirt 177675; warcraft.wiki.gg/wiki/Undercroft (crypt in the southwest, Tirion''s substitute grave, Zaeldarr raids the grave pit)'),
(13904, 1, 139, 4, 0, 0, 'Darrowshire', 'Darrowshire, named for Darrowmere Lake to its west, was a village of humble, hardworking folk in the southern foothills, until the Scourge came. Its militia under Captain Joseph Redpath, a company of troops and paladins of the Silver Hand stood against the ghoul lord Horgus and the death knight Marduk the Black, and the battle was nearly won before Redpath was corrupted and the defenders turned on their own. Now the village is silent ruin. In one house the ghost of a little girl, Pamela Redpath, still waits for her father to come home, and pieces of her lost doll lie scattered through the town.', 'page_text 2371-2376 (Annals of Darrowshire: named from Darrowmere Lake, southern foothills, humble yet hardworking, militia, troops, paladins, Horgus, Marduk, corruption, betrayal); quest 5149 description (stay in our house, doll left in town); zone_areas 2262: Pamela Redpath 10926, Pamela''s Doll''s Head/Left Side/Right Side 176116, 176142, 176143, Ghost of the Past 10940; warcraft.wiki.gg/wiki/Darrowshire (silent ruins, ghosts and memories)'),
(13905, 1, 139, 5, 0, 0, 'Corin''s Crossing', 'Corin''s Crossing grew up where the roads met between Andorhal, Darrowshire, Stratholme and Tyr''s Hand. The Scourge holds it now. Dark casters and summoners of the Cult of the Damned work among ghouls, shriekers and stitched horrors, and unseen servants walk its streets. Many of its ghouls were once the good folk of Darrowshire, still bound in their rotting bodies. Old battles cling to the place: near here a dwarf captain shattered the sword of Marduk the Black on his shield, and here too the Argent Dawn found the wounded Carlin Redpath wandering in fever days after his village fell.', 'warcraft.wiki.gg/wiki/Corin%27s_Crossing (crossroads between Andorhal, Darrowshire, Stratholme and Tyr''s Hand; Scourge and Cult of the Damned); zone_areas 2264: Hate Shrieker, Vile Tutor, Dark Caster, Gibbering Ghoul, Dark Summoner, Stitched Horror, Unseen Servant, Scourge Warder; creature_template subnames: Dark Summoner, Vile Tutor <Cult of the Damned>; quest 5211 description (defenders roam as servants of the Scourge, in Plaguewood and Corin''s Crossing); page_text 2384 (sword shattered near Corin''s Crossing on a dwarf captain''s shield); page_text 2391 (Carlin found near Corin''s Crossing)'),
(13906, 1, 139, 6, 0, 0, 'The Infectis and Pestilent Scars', 'Two great wounds cut the land west and south of Corin''s Crossing. The Infectis Scar was made by dark magic. When the rune-laden sword of Marduk the Black broke against a dwarf''s shield, the blade sank into the earth and corrupted it, eating out the gorge that bears its sickness still; the shattered sword lies at its bottom, and spectral marauders and corpses stalk its floor. The Pestilent Scar is a natural rift, but the plague has found it all the same. Living decay and rotting sludges ooze along both gorges, and the bones of the land show through the rock.', 'page_text 2384 (Marduk''s rune-laden sword sank into the earth, gorge now known as the Infectis Scar); quest 5181 description (sword lies at the bottom of the gorge west of Corin''s Crossing); warcraft.wiki.gg/wiki/Infectis_Scar (caused by dark magic, unlike the natural Pestilent Scar); zone_areas 2623: Shattered Sword of Marduk 176209, Spectral Marauder, Spectral Corpse, Living Decay, Rotting Sludge; 2622: Living Decay, Rotting Sludge'),
(13907, 1, 139, 7, 0, 0, 'Blackwood Lake', 'Blackwood Lake lies northwest of Corin''s Crossing, its waters fouled and stalked by plague monstrosities. A town named Blackwood once stood here, burned by orcs in the Second War and remembered as the home of Grand Marshal Othmar Garithos. Its waters hold a darker relic. After the Battle of Darrowshire the Scourge carried off the skull of the fallen ghoul lord Horgus to spread dread, and when paladins of the Silver Hand destroyed the company that bore it, they cast the skull into the lake. Spectral betrayers and defenders still fight along its shores, as if that night has never ended.', 'quest 5181 description (lake northwest of Corin''s Crossing, his skull remains there); page_text 2383 (skull carried to sow dread, company defeated by Silver Hand paladins, cast into Blackwood Lake); warcraft.wiki.gg/wiki/Blackwood_Lake (town of Blackwood, home of Othmar Garithos); warcraft.wiki.gg/wiki/Eastern_Plaguelands (Second War: orcs burned Blackwood); zone_areas 2624: Horgus'' Skull 176208, Spectral Betrayer 11288, Spectral Defender 11289, Plague Monstrosity, Blighted Horror; warcraft.wiki.gg/wiki/Eastern_Plaguelands (orcs burned the small town of Blackwood in the Second War)'),
(13908, 1, 139, 8, 0, 0, 'Tyr''s Hand', 'In the southeast stands Tyr''s Hand, a walled city named for an ancient keeper and one of the oldest holy sites of the Church of the Light. The Scarlet Crusade rules it now as its stronghold in the east. Warders, praetorians, clerics and archmages fill its streets, inquisitors keep their own grim watch, and the Scarlet Basilica rises at its heart. Crusader Lord Valdelmar commands within, with High General Abbendis close at hand, and each day a courier rides in with reports from the Crusade''s command in Stratholme. A camp outside the walls marks how far the Crusade dares to reach.', 'warcraft.wiki.gg/wiki/Tyr%27s_Hand (named for Keeper Tyr, one of the oldest holy sites, Valdelmar held the city, Scarlet Basilica); zone_areas 2266: Scarlet Warder, Enchanter, Cleric, Praetorian, Curate, Archmage, Inquisitor, Valdelmar 11898, High General Abbendis 10828; 2265 Scarlet Base Camp: Scarlet Warder, Enchanter, Cleric; quest 6145 description (each day a report is sent from their central command to Tyr''s Hand); quest 6146 description (deliver to Crusader Lord Valdelmar in Tyr''s Hand)'),
(13909, 1, 139, 9, 0, 0, 'Light''s Hope Chapel', 'Light''s Hope Chapel was among the oldest and most revered holy sites of the Eastweald, and the remains of Lordaeron''s heroes lie in the catacombs beneath it. The Argent Dawn has made it the headquarters of its war on the Scourge, under Lord Maxwell Tyrosus. Horde and Alliance alike are welcome. Envoys of the Cenarion Circle, the Earthen Ring and even the Scarlet Crusade sit beside the Dawn''s own Brotherhood of the Light, and a caretaker tosses the corpses carried in from the field into a pit below. The chapel''s holy ground has already been tested. When the death knights of Acherus marched on it, the Light beneath it helped turn them back.', 'warcraft.wiki.gg/wiki/Light%27s_Hope_Chapel (one of the oldest and most revered holy sites in the Eastweald, Sanctum of Light catacombs with heroes'' remains, Argent Dawn HQ); warcraft.wiki.gg/wiki/Eastern_Plaguelands (travel hub for both factions, led by Lord Maxwell Tyrosus); zone_areas 2268: Rayne 16135 <Cenarion Circle>, Rimblat Earthshatter 16134 <The Earthen Ring>, Scarlet Commander Marjhan 16114, Brotherhood of the Light NPCs, Caretaker Alen 11038; npc_text 8354 (Marjhan: emissary of the Scarlet Crusade), npc_text 3935 (Alen: I toss them in the pit); creature_text 29175 groups 28, 29 and 29173 group 85 (what lies beneath the chapel; the Light of Dawn); creature_text 29173 groups 26, 85 (We have lost. The Light... this place; the Light of Dawn is uncovered)'),
(13910, 1, 139, 10, 0, 0, 'The Noxious Glade', 'North of Light''s Hope Chapel the ground sinks into the Noxious Glade, a sickly hollow held by the Scourge. Shadowmages and dark adepts of the cult keep company with stitched golems, dread weavers and hulking Scourge champions, some of them veterans of the slaughter at Darrowshire, and a cult deathspeaker named Selendre is sometimes seen among them. From the glade a passage leads through to Death''s Breach, where the death knights of the Ebon Blade now gather with their risen servants.', 'zone_areas 2270: Shadowmage, Dark Adept, Stitched Golem, Dread Weaver, Scourge Champion, Deathspeaker Selendre 10827 <Cult of the Damned> (rare), Knight of the Ebon Blade, Risen Drudge; quest 5206 description (scourge champions who took part in the battle of Darrowshire, Noxious Glade to the north); warcraft.wiki.gg/wiki/Eastern_Plaguelands (from the Noxious Glade a cave leads to Death''s Breach)'),
(13911, 1, 139, 11, 0, 0, 'Northdale', 'Northdale was a hamlet in the northeast until the war tore through it. When the Order of the Silver Hand was shattered after Uther''s death, a young paladin named Taelan Fordring was driven back here and made his last stand, wondering whether any of his order still lived. Here he threw down its standard and renounced all he had known, and the tattered banner still lies on the ground where it fell. Banshee death singers and unseen eyeless watchers haunt the ruins now, and west of the town crawls Borelgore, a bloated maggot beast that has cost the Blightcaller whole regiments.', 'quest 5845 description (pushed to Northdale, final stand, threw down the standard); quest 5845 reward text (tattered state); zone_areas 2272: Symbol of Lost Honor 177264, Death Singer, Eyeless Watcher; warcraft.wiki.gg/wiki/Northdale (haunted by banshees and invisible eyeless watchers); quest 6136 description (Borelgore west of Northdale, lost entire regiments)'),
(13912, 1, 139, 12, 0, 0, 'Zul''Mashar', 'Zul''Mashar in the far northeast is the capital of the Mossflayers, a small tribe of forest trolls worn down by long wars with the humans of Lordaeron. The plague has found them too. Some Mossflayers who ate tainted meat on the road to Zul''Mashar began to hear a lich urging them to carry the sickness into the city, and one of them, Hameya, wrote a plea to be killed before the last of that will was gone. Shadowhunters, scouts and cannibals crowd the ruins under Warlord Thresh''jin, and above them rises the ziggurat of Mazra''Alor. Scholars seek the Mosh''aru tablets held here, said to speak of Hakkar.', 'warcraft.wiki.gg/wiki/Zul%27Mashar (capital of the Mossflayer tribe, small forest troll tribe, long fighting with the humans of Lordaeron, Mazra''Alor ziggurat, Thresh''jin); quest 6024 description (Hameya: ate bad meat, the lich''s words urging me to reach Zul''Mashar and infect more); zone_areas 2273: Mossflayer Shadowhunter, Cannibal, Scout, Warlord Thresh''jin 10822, Infiltrator Hameya 12248, Third and Fourth Mosh''aru Tablets; quest 5065 description (tablets held by mossflayer trolls; first tablets spoke of the essence of Hakkar)'),
(13913, 1, 139, 13, 0, 0, 'Quel''Lithien Lodge', 'In the northern hills, near the road that leads on to Quel''Thalas, stands Quel''Lithien Lodge, a hunting lodge of the high elves that once hosted Farstrider rangers. Rangers, pathstriders and woodsmen keep it still under Ranger Lord Hawkspear, friendly to the Alliance and quick to draw on the Horde. Among their papers is the Quel''Thalas Registry, a record that Nathanos Blightcaller wants back badly enough to send killers for it. Nearby lives the priestess Aurora Skycaller, who grieves that her people are as shattered as any broken relic, yet will mend an old highborne crystal for those who ask sincerely.', 'warcraft.wiki.gg/wiki/Quel%27Lithien_Lodge (high elven hunting lodge near the entrance to Quel''Thalas, Farstrider camp, friendly to Alliance until Cataclysm); zone_areas 2276: Ranger, Woodsman, Pathstrider, Ranger Lord Hawkspear 10824, Quel''Thalas Registry 177747, Aurora Skycaller 10304; FactionTemplate 1576: hostile to Horde, not to Alliance; quest 6133 description (registry, a document detailing my life); npc_text 5817 (my people are as shattered as the relic); quests 5246, 5247, 5248 (Crystal of Zin-Malor)'),
(13914, 1, 139, 14, 0, 0, 'The Watchtowers', 'Four old towers of Lordaeron stand over the Eastern Plaguelands: Crown Guard Tower in the south, Eastwall Tower, the Northpass Tower near the road to the north, and Plaguewood Tower at the edge of the blighted forest. All were left empty when the kingdom fell. Now the Alliance means to seize and rebuild them, tightening a noose around the Forsaken lands to the west, while the Horde has learned of the plan and fights to drive them out. Envoys of both sides wait at Light''s Hope Chapel for news of who holds the towers.', 'quest 9664 description (towers long abandoned since the days of Lordaeron, seized and rebuilt, tighten the noose); quest 9665 description (Forsaken agents uncovered the Alliance plot; drive them out); zone_areas: Tower Banner 182106 and capture doodads in 2263, 2271, 2275, 4067; Emissary Whitebeard 17069 and Gormok 17072 in 2268; warcraft.wiki.gg/wiki/Crown_Guard_Tower (destroyed in the Scourge invasion, contested by Alliance and Horde)'),
(13915, 1, 139, 15, 0, 0, 'Plaguewood', 'The Plaguewood spreads south of Stratholme, the most diseased corner of a diseased land. It was once a fair woodland that Prince Arthas crossed on his road to the city; since the Culling the blight has swollen it with giant mushrooms and rot. The Scourge has raised ziggurats and slaughterhouses among the trees, guarded by stitched horrors, cannibal ghouls and cursed mages, and the Argent Dawn pays demolition crews to bring them down. For years the necropolis Naxxramas hung above this forest, and the Dawn controlled the way in. It has since floated away to Northrend, leaving only the scars beneath.', 'warcraft.wiki.gg/wiki/Plaguewood (south of Stratholme, most infested part, once beautiful woodland, Arthas crossed it, giant mushrooms, ziggurats and slaughterhouses, Naxxramas floated above and left for Dragonblight, Argent Dawn controlled access); quests 6026, 6041 (Smokey''s Argent Dawn demolition of ziggurats and slaughterhouses); zone_areas 2277: Stitched Horror, Cannibal Ghoul, Cursed Mage, Scourge Structure, Ziggurat/Slaughterhouse Protector'),
(13916, 1, 139, 16, 0, 0, 'Terrordale', 'Terrordale was a small town at the western edge of the Plaguewood, now a ghost town of plagued swine and Scourge soldiers. It still has a merchant. Augustus the Touched was lodging at the inn when the Scourge came, and he has been here ever since, eager to buy and sell anything at prices he calls insane, if only someone would fetch the receipt book he left in his room. Sharing his house is Egan, a dwarf who hates the Scourge but pities its victims, and who has built a blaster to free the restless souls of Stratholme.', 'warcraft.wiki.gg/wiki/Terrordale (small town at the edge of Plaguewood, ruined ghost town); zone_areas 2627: Plagued Swine, Scourge Soldier, Augustus the Touched 12384, Egan 11140, Augustus'' Receipt Book; npc_text 4979, 4980; creature_text 12384; quest 6164 description (room in the inn); warcraft.wiki.gg/wiki/Augustus_the_Touched (staying at the inn when the Scourge came); warcraft.wiki.gg/wiki/Egan (dwarf living in Augustus'' house); quests 5281, 5282 (Egan, compassion, blaster)'),
(13917, 1, 139, 17, 0, 0, 'Stratholme', 'Stratholme was the second city of Lordaeron and the seat of the Eastweald. When the plague reached it in tainted grain, Prince Arthas ordered its people put to death before they could rise, and the city burned. Many chose the flames over becoming Scourge, and their restless spirits still walk its streets. Today Baron Rivendare holds most of the city for Kel''Thuzad, while the Scarlet Crusade has walled itself into the Scarlet Bastion under its Grand Crusader. On its eastern side, at Eastwall Gate, a service entrance leads into the Elders'' Square.', 'warcraft.wiki.gg/wiki/Stratholme (second largest city, tainted grain from Andorhal, the Culling, Rivendare under Kel''Thuzad, Scarlet Bastion under the Grand Crusader); quest 5281 description (many hurled themselves into the flames rather than become Scourge; restless spirits); quest 5263 description (Rivendare, Kel''Thuzad''s errand boy); quest 6144 reward text (Grand Crusader sits safely in the Scarlet Bastion); zone_areas 2625: Elders'' Square Service Entrance 175369'),
(13918, 2, 139, 1, 0, 0, 'Tirion Fordring', 'Tirion Fordring was a paladin of the Silver Hand and Lord of Mardenholde, master of Hearthglen. When he defended an honorable orc against his own people, he was tried for treason, stripped of his rank and exiled, and his young son Taelan was told he had died. Tirion stayed close, living as a hermit in a hut by the Thondroril with his horse Mirador, watching from afar as Taelan grew up to become Highlord of the Scarlet Crusade. He believes race does not dictate honor. In time his son''s death pulled him from his long malaise: he vowed a new Order of the Silver Hand, fought at Light''s Hope Chapel, and now leads the Argent Crusade.', 'warcraft.wiki.gg/wiki/Tirion_Fordring (Silver Hand, Lord of Mardenholde, Eitrigg, trial and exile, hermit by the Thondroril with Mirador, Argent Crusade); npc_text 4494 (banished, chose to remain to watch over Taelan; Taelan their Highlord); quest 5781 description (his mother told him I had died); npc_text 4254 (race does not dictate honor; orcs as honorable as knights); creature_text 12126 groups 6, 7 (malaise; a new Order is born); creature_text 29175 (Tirion at Light''s Hope Chapel)'),
(13919, 2, 139, 2, 0, 0, 'Nathanos Blightcaller', 'In life Nathanos Marris was a ranger lord of Lordaeron, trained by the high elves to a rank no other human had held. The Scourge overran him on his own farm, and he woke as one of its mindless dead until Sylvanas Windrunner came for him and broke the Lich King''s hold. He became among the first of her champions. Now the Blightcaller keeps the Marris Stead with his hounds, hunts Scourge and Alliance alike, and trains the recruits the Dark Lady sends him with open contempt, calling every one of them imbecile. He guards the secrets of his mortal life jealously. To the Alliance he is a hero lost, and a traitor to be destroyed.', 'quest 6186 description (the only human ever allowed to train under the high elves); quest 6163 description (stood on this stead, woke as Scourge, she came for me); quest 5961 description (among the first of my champions; slaying all Scourge and Alliance); npc_text 4814; quests 6022, 6133, 6135 (imbecile; do not read the registry); quest 6187 description (Order Must Be Restored: destroy the Blightcaller); FactionTemplate 1174: hostile to Alliance'),
(13920, 2, 139, 3, 0, 0, 'Lord Maxwell Tyrosus', 'Lord Maxwell Tyrosus leads the Argent Dawn from Light''s Hope Chapel. A veteran of the Third War who fought beside Uther the Lightbringer, he left the Silver Hand when it hardened into the Scarlet Crusade and rose to command the Dawn. He keeps to the church and grants audience to outsiders only rarely; years can pass between such honors, and the Argent Hold, the Dawn''s sealed vault, stays locked until a champion has truly earned it. When death knights marched on the chapel, Tyrosus rallied the defenders and urged them to hold fast, for the Light would prevail.', 'warcraft.wiki.gg/wiki/Maxwell_Tyrosus (fought with Uther at Andorhal, left when the Silver Hand became the Scarlet Crusade, leader of the Argent Dawn, Second Battle); quest 5264 description (years since Maxwell has granted audience to outsiders; inside the church); quest 5265 description (the Argent Hold has remained locked through the years); creature_text 29178 group 7 (Stand fast, brothers and sisters! The Light will prevail!)'),
(13921, 2, 139, 4, 0, 0, 'Duke Nicholas Zverenhoff', 'Duke Nicholas Zverenhoff is one of the Argent Dawn''s most respected leaders. He issues the Dawn''s commission to all who fight under its banner and pays for the scourgestones they bring back as proof. He holds that anything taken to an extreme endangers the world, the Scarlet Crusade''s blind zealotry above all, and he counsels his champions to be tolerant yet rigid in their beliefs. It was to Zverenhoff that the proof came that the Grand Crusader in Stratholme was a dreadlord, brother to Varimathras, leaving him to wonder how long the Crusade had served a demon unaware.', 'warcraft.wiki.gg/wiki/Nicholas_Zverenhoff (one of the Dawn''s most respected leaders); quest 5503 reward text (all who fight on behalf of the Argent Dawn must don our commission; scourgestones); quest 5251 description and request text (anything taken to an extreme; tolerant yet rigid); quest 5262 description and reward text (Grand Crusader a demon, brother to Varimathras; pawns of a greater evil)'),
(13922, 2, 139, 5, 0, 0, 'Leonid Barthalomew the Revered', 'Leonid Barthalomew died in the Scourging of Lordaeron and served the Lich King as a mindless thrall, until the Banshee Queen set him free. He chose the Argent Dawn over the Forsaken. He treats his undeath as a malady to be endured and a weapon to be turned on the Scourge, and cares nothing for the reverence his colleagues show him. In Stratholme he watched the mage Ras Frostwhisper cut his own throat and rise as a lich, and he would rather not remember it. He has played tricks of his own on the Scourge, and he held the chapel''s defense against the death knights until Tirion Fordring came.', 'quest 5462 description (undead dissenter of the Scourge, freed by the Banshee Queen but loyal to the Argent Dawn); quest 5243 description (undeath a malady; accolades mean nothing); quest 5463 description (watched Ras Frostwhisper become a lich); quest 5462 request text (questions you do not want answers); warcraft.wiki.gg/wiki/Leonid_Barthalomew_the_Revered (killed in the Scourging, led the defense until Tirion arrived); burning_steppes.json 4624 (his trick on Vectus, mentioned only in passing); warcraft.wiki.gg/wiki/Leonid_Barthalomew_the_Revered (led the Argent Dawn against the death knights before Tirion arrived)'),
(13923, 2, 139, 6, 0, 0, 'Carlin Redpath', 'Carlin Redpath is the brother of Captain Joseph Redpath and the uncle of little Pamela. He fell, terribly wounded, at the battle of Darrowshire, and days later agents of the Argent Dawn found him wandering near Corin''s Crossing, weak with thirst and fever. They carried him to Light''s Hope Chapel, and in gratitude he joined their ranks. His war on the Scourge is a war of revenge. He still dreams of his village''s defenders crying out to him, and at night, far away in Darrowshire, his ghostly niece can hear him weeping.', 'page_text 2391 (The Fate of Carlin Redpath); quest 5211 request text (defenders cry out to me in my dreams); quest 5241 description and reward text (I can hear my Uncle Carlin crying; duty to revenge); npc_text 4716; posarea: Carlin 11063 in area 2268'),
(13924, 2, 139, 7, 0, 0, 'Pamela Redpath', 'Pamela Redpath was a little girl when the Scourge came to Darrowshire. Her aunt Marlene hid her in the family home and told her to stay put while her father went to fight, and she has stayed ever since. Her ghost does not understand what happened. She waits for her daddy, asks after her aunt and uncle, misses the big sister, Jessica, who went away crying long ago, and wants her doll, which she left in town. Sometimes bad people come and whisper to her. Jessica lives still, far away in Winterspring, and has asked strangers to look for her.', 'quest 5149 description (auntie told me to stay; father had to fight; bad people whisper; doll); quest 5601 description and reward text (Jessica fled; Pamela on Jessica crying); quests 5152, 5241 (aunt and uncle); quest 5142 description (Marlene hid her niece); DB: Jessica Redpath 11629 spawned on map 1 at Everlook, Winterspring; warcraft.wiki.gg/wiki/Pamela_Redpath (youngest daughter of Joseph, killed in the battle)'),
(13925, 2, 139, 8, 0, 0, 'Joseph Redpath', 'Captain Joseph Redpath led Darrowshire''s militia when the Scourge attacked, and he fought bravely until the death knight Marduk the Black rode up to him in the thick of battle and tore his spirit loose with black magic. Twisted into an evil shadow of himself, he spread his taint among the defenders, who turned on their allies and slaughtered the town. His cracked shield was cast aside, his corrupted spirit went on to ravage Lordaeron, and his daughter Pamela was left waiting for him. Only by changing the course of that battle can his soul be won back.', 'page_text 2372, 2375, 2376 (Annals: militia, Marduk tore loose his spirit, defenders betrayed and slaughtered the town, tore into Lordaeron); quest 5168 description (shield cracked and discarded); quest 5721 description (Redpath must survive to be corrupted, then defeated; his spirit saved); creature 10936 Joseph Redpath (gossip, spirit after the battle), 10938 Redpath the Corrupted (hostile)'),
(13926, 3, 139, 1, 0, 0, 'The Fordring Redemption', 'The hermit by the Thondroril asks small things first: thin the plaguehounds, clear the plaguebats from the sky, bring carrion worm meat for his larder. Only when he trusts a stranger does he tell the truth. He is Tirion Fordring, exiled for treason, and his son Taelan, now Highlord of the Scarlet Crusade, believes him dead. Tirion asks for help to make the boy remember who he was. From the false grave at the Undercroft comes the toy hammer Taelan buried there as a child. From Northdale comes the Silver Hand standard he threw down. On Caer Darrow the ghost of the artist Renfray reveals where he hid his painting of the Fordrings on the beach, and it is found beneath the paint of a picture of the twin moons, deep in the Scarlet Bastion of Stratholme. Tirion weeps over it, then sends the gifts to Myranda, whose illusions alone can carry them into Hearthglen.', 'quests 5542, 5543, 5544 descriptions and reward texts; quest 5742 and gossip menus 3681-3683 (npc_text 4493-4495); quests 5781, 5845, 5846, 5848 descriptions and reward texts; quest 5861 description; quest 5848 description (search for a painting of our twin moons, chip away at the paint)'),
(13927, 3, 139, 2, 0, 0, 'In Dreams', 'Disguised by Myranda''s illusion, a stranger reached Mardenholde Keep and laid Tirion''s gifts before Highlord Taelan Fordring. The truth undid him. For years, he confessed, he had been the Grand Crusader''s puppet, kept alive only by memories of his father and dreams of fighting at his side. He asked to be taken to Tirion. Taelan led the way out of Hearthglen, but Grand Inquisitor Isillien met them on the road with his Crimson Elite, charged by the Grand Crusader to destroy him. Taelan fell. Then Tirion himself arrived, and the old man who had sat idle for so long fought the Inquisitor down and knelt over his son''s body. There he made a vow: a new Order of the Silver Hand would be born that day, sworn to stamp out the evil that afflicts this world, and he would be its Highlord.', 'quest 5862 log and reward text (Scarlet Illusion, Mardenholde Keep); quest 5944 description and reward text; creature_text 1842, 1840 (Isillien: forest''s edge, Grand Crusader charged me), 12126 (murdered my boy; too long have I sat idle; a new Order is born); warcraft.wiki.gg/wiki/Tirion_Fordring (Isillien killed Taelan in Hearthglen; Tirion avenged his son); creature_text 1840 group 0 (you will not make it to the forest''s edge)'),
(13928, 3, 139, 3, 0, 0, 'Little Pamela', 'Two women ask after the same child. In Winterspring, Jessica Redpath, who fled Lordaeron before the Scourge came, begs for news of her little sister. On a hill south of Andorhal, the ghost of Marlene Redpath longs to know what became of the niece she hid when the battle began. Both point to Darrowshire, where Pamela''s ghost waits in her house, still trusting that her father will come home. She asks only for her doll, left somewhere in the ruined town, and is overjoyed to have it back. Then she sends her new friend to Auntie Marlene, who cannot bear to tell her what became of Joseph, and to Uncle Carlin, whom she hears crying at night far to the east. At Light''s Hope Chapel the news breaks Carlin''s heart and hardens his vow of revenge.', 'quests 5142, 5601, 5149, 5152, 5241 descriptions and reward texts; creature_text 10926 group 4 (Hurray! My doll!)'),
(13929, 3, 139, 4, 0, 0, 'The Annals of Darrowshire', 'The bronze dragon Chromie believes the fate of Joseph Redpath can still be changed, but first it must be learned. The Annals of Darrowshire, recovered from Andorhal''s city hall, tell an ugly tale: in the middle of the battle the captain was corrupted by Marduk the Black, and his taint turned the defenders against their own allies. Chromie''s magic adds new pages that run beyond that night, and they lead to Light''s Hope Chapel and Joseph''s surviving brother, Carlin. Carlin sends for the relics of the battle: Davil Lightfire''s libram from the town hall of Hearthglen, Redpath''s cracked shield from Gahrron''s Withering, the skull of Horgus from Blackwood Lake and the shattered sword of Marduk from the gorge west of Corin''s Crossing. Meanwhile he asks that the fallen defenders, now ghouls in the Scourge''s service, be released from their misery.', 'quests 5154, 5210 descriptions and reward texts; quests 5168, 5181 descriptions; quest 5211 description; page_text 2371-2391 (Annals and Extended Annals)'),
(13930, 3, 139, 5, 0, 0, 'The Battle of Darrowshire', 'Chromie says the relics are reagents for a great spell, and one more is needed: skulls of the Scourge champions who fought at Darrowshire, found in the Noxious Glade and the Fungal Vale by a crystal that resonates at their touch. Carlin gathers the relics together and sends them on to her in the ruined inn of Andorhal. The spell raises the spirits of Darrowshire, and when the bundle is set in the town square the battle is fought again. Davil Lightfire must live until Horgus falls; Captain Redpath must survive long enough to be corrupted, and then be defeated, so that his spirit is saved. When it is done, Joseph appears in the square and goes home at last. Pamela, overjoyed, says her daddy chased the ghosts away, and she has made tea with lots of sugar, and her father leaves a key to a chest behind the house.', 'quests 5206, 5941, 5721, 5942 descriptions and reward texts; creature_text 10936 (Pamela? ... I''m finally home), 10944, 10937, 10938, 10948 (battle lines)'),
(13931, 3, 139, 6, 2, 0, 'The Blightcaller''s Imbeciles', 'Sylvanas sends her promising soldiers east to Nathanos Blightcaller, one of the first of her champions, and he greets each as fodder for his hounds. Training at the Marris Stead is whatever he needs done. Recruits fetch living rot from the Scourge of Corin''s Crossing and grind it down to feed the blighthounds, clear the plaguebats from his fields, raid Quel''Lithien Lodge for a registry of his mortal life that they are forbidden to read, and hunt Duskwing, an albino demon bat, and Borelgore, a maggot beast that has cost him whole regiments. The last task is his own. In life Nathanos was cut down on this farm by the abomination Ramstein and woke as Scourge; freed by Sylvanas, he chased it for months until it fled into Stratholme. Whoever brings back its head earns his salute and a place among his champions.', 'quests 5961, 6022, 6042, 6133, 6135, 6136, 6163 descriptions, request and reward texts'),
(13932, 3, 139, 7, 2, 0, 'The Scarlet Oracle', 'When the Undercity resolved to strike back at the Scarlet Crusade, whose Grand Crusader sits safe in the Scarlet Bastion while his soldiers desecrate Forsaken lands, Nathanos was ordered to send his most capable agents. His best had died years ago, so he sent what he had. Forsaken deathstalkers had learned that a daily report travels from the Crusade''s command in Stratholme to Tyr''s Hand. The Crimson Courier was killed, the command rewritten, and a soldier who had bitten into one of Nathanos''s rotten apples walked into Tyr''s Hand wearing a crusader''s face to hand it to Crusader Lord Valdelmar. The forged order summoned Demetria, the Scarlet Oracle and the Grand Crusader''s chief advisor, to Stratholme. Her otherworldly senses did not save her from the ambush on the road.', 'quests 6144, 14349 descriptions and reward texts; quests 6145, 14350 descriptions; quests 6146, 6147, 6148 descriptions and reward texts; disables table: quests 6144 and 6145 disabled'),
(13933, 3, 139, 8, 0, 0, 'The Light of Dawn', 'Seen from Light''s Hope Chapel, it began as the end of the world. Highlord Darion Mograine marched the Lich King''s army and the death knights of Acherus against the chapel, and Korfax, Lord Maxwell Tyrosus, Leonid Barthalomew, Duke Zverenhoff and the Dawn''s defenders held as long as they could. Darion''s own blade, the corrupted Ashbringer, had begun to defy him, and more than a hundred defenders had fallen when Tirion Fordring arrived. Tirion told Darion that his master knew what lay beneath the chapel and had sent him to die. The spirit of Alexandros Mograine came to his son, then the Lich King appeared, admitted it, struck down the defenders and seized Tirion. Darion turned on him and threw the Ashbringer to Tirion, in whose hands it was cleansed. Struck by the blade, the Lich King withdrew, swearing their next meeting would not be on holy ground. There Tirion called for union, and the Argent Crusade was born.', 'zone_the_scarlet_enclave.cpp (npc_highlord_darion_mograine Light of Dawn event: defenders Korfax 29176, Eligor 29177, Tyrosus 29178, Leonid 29179, Zverenhoff 29180, Rayne 29181, Rimblat 29182); creature_text 29173 groups 68-85 (army marches, over a hundred Defenders fall before Tirion arrives, Ashbringer thrown and cleansed, Alexandros arrives); creature_text 29175 groups 28-29, 53-66 (what lies beneath the chapel; union; The Argent Crusade comes for you); creature_text 29183 groups 47-58 (Lich King: draw Tirion out; not on holy ground); warcraft.wiki.gg/wiki/Light%27s_Hope_Chapel (Second Battle)');
